package com.example.paymentservicefeb25.repositories; import com.example.paymentservicefeb25.models.PaymentIdempotency; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.Optional; public interface PaymentIdempotencyRepository extends JpaRepository<PaymentIdempotency,Long>{Optional<PaymentIdempotency> findByIdempotencyKey(String key); @Modifying @Query(value="INSERT IGNORE INTO payment_idempotency (idempotency_key, order_id, payment_id, created_at) VALUES (:key, :orderId, NULL, CURRENT_TIMESTAMP)", nativeQuery=true) int claimKey(@Param("key")String key,@Param("orderId")Long orderId);}
